await pactum.spec()
  .post('http://localhost:8080/graphql')
  .withGraphQLQuery(`
    mutation {
      addCategory(name: "Validação Contrato Categoria") {
        id
        name
      }
    }
  `)
  .expectStatus(200)
  .expectJsonSchema({
    type: 'object',
    properties: {
      data: {
        type: 'object',
        properties: {
          addCategory: {
            type: 'object',
            properties: {
              id: { type: 'string' },
              name: { type: 'string' }
            },
            required: ['id', 'name']
          }
        }
      }
    }
  });

await pactum.spec()
  .post('http://localhost:8080/graphql')
  .withGraphQLQuery(`
    mutation {
      addProduct(name: "Monitor Gamer", price: 1200.0) {
        id
        name
        price
      }
    }
  `)
  .expectStatus(200)
  .expectJsonSchema({
    type: 'object',
    properties: {
      data: {
        type: 'object',
        properties: {
          addProduct: {
            type: 'object',
            properties: {
              id: { type: 'string' },
              name: { type: 'string' },
              price: { type: 'number' }
            },
            required: ['id', 'name', 'price']
          }
        }
      }
    }
  });

const response = await pactum.spec()
  .post('http://localhost:8080/graphql')
  .withGraphQLQuery(`
    mutation {
      addCategory(name: "Eletrônicos") {
        id
        name
      }
    }
  `)
  .expectStatus(200);
categoryId = response.body.data.addCategory.id;

await pactum.spec()
  .post('http://localhost:8080/graphql')
  .withGraphQLQuery(`
    mutation {
      editCategory(id: "${categoryId}", name: "Tecnologia & Eletrônicos") {
        id
        name
      }
    }
  `)
  .expectStatus(200);

